// Rule L12: an enumerator spelled the engine's way becomes the catalog's spelling.
/// @name DreamShaderTests/Migrate/M_MgEnum
export void M_MgEnum(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    Color = UE.SceneTexture(SceneTextureId = SceneColor).Color.rgb;
    Base.EmissiveColor = Color;
}
